      ipaUs: "/ju\u02d0 \u02c8\u0251\u02d0n\u0259stli b\u026a\u02c8li\u02d0v \u00f0\u00e6t?/",
      keywords: ["honestly believe"],
      explanationAi: "Sheldon ch\u1ea5t v\u1ea5n s\u1ef1 hi\u1ec3u bi\u1ebft h\u1eddi h\u1ee3t c\u1ee7a v\u1ecb t\u1ef7 ph\u00fa.",
