      ipaUs: "/a\u026a b\u026a\u02c8li\u02d0v wi\u02d0 h\u00e6v tu\u02d0 l\u028ak tu\u02d0 \u02c8\u0261r\u00e6v\u0259ti \u00e6nd \u026ats \u02c8m\u00e6\u0261n\u026a\u02cctu\u02d0d./",
      keywords: ["gravity", "magnitude"],
      explanationAi: "V\u1ecb t\u1ef7 ph\u00fa b\u1eaft \u0111\u1ea7u thuy\u1ebft gi\u1ea3ng v\u1ec1 c\u00e1c \u00fd t\u01b0\u1edfng vi\u1ec3n v\u00f4ng.",
      properNouns: [],
