      ipaUs: "/\u026at k\u028ad bi\u02d0 \u0259 r\u026a\u02c8p\u028cls\u026av f\u0254\u02d0rs \u026af ju\u02d0 d\u0292\u028cst \u00e6d \u02c8n\u025b\u0261\u0259t\u026av m\u00e6s./",
      keywords: ["repulsive force", "negative mass"],
      explanationAi: "Gi\u1ea3 thuy\u1ebft v\u1ec1 kh\u1ed1i l\u01b0\u1ee3ng \u00e2m v\u00e0 l\u1ef1c \u0111\u1ea9y tr\u1ecdng l\u1ef1c.",
      properNouns: [],
