      ipaUs: "/tu\u02d0 bi\u02d0 kl\u026ar, \u00f0e\u026a w\u025c\u02d0r \u0254\u02d0l \u02c8o\u028av\u0259r \u02cce\u026a\u02c8ti\u02d0n./",
      keywords: ["over eighteen", "to be clear"],
      explanationAi: "Th\u1ea7y Givens v\u1ed9i v\u00e0ng \u0111\u00ednh ch\u00ednh tr\u01b0\u1edbc h\u1ecdc sinh.",
      properNouns: [],
      tokenCount: 8,
