      startTime: 599.0,
      endTime: 603.5,
      text: "Well, it is hard to explain. The math is pretty complicated.",
      translationVi: "Ch\u00e0, \u0111i\u1ec1u n\u00e0y kh\u00f3 gi\u1ea3i th\u00edch l\u1eafm. C\u00e1c ph\u00e9p to\u00e1n ph\u1ee9c t\u1ea1p v\u00f4 c\u00f9ng.",
      ipaUs: "/w\u025bl, \u026at \u026az h\u0251\u02d0rd tu\u02d0 \u026ak\u02c8sple\u026an. \u00f0\u0259 m\u00e6\u03b8 \u026az \u02c8pr\u026ati \u02c8k\u0251\u02d0mpl\u026a\u02ccke\u026at\u026ad./",
      keywords: ["hard to explain", "math is complicated"],
      explanationAi: "Hodges vi\u1ec7n c\u1edb to\u00e1n h\u1ecdc \u0111\u1ec3 g\u1ea1t \u0111i.",
