      startTime: 661.0,
      endTime: 665.0,
      text: "I am sure Dr. Hodges will see you as soon as he can.",
      translationVi: "T\u00f4i tin ch\u1eafc Ti\u1ebfn s\u0129 Hodges s\u1ebd ti\u1ebfp hai cha con ngay khi \u00f4ng \u1ea5y r\u1ea3nh \u1ea1.",
      ipaUs: "/a\u026a \u00e6m \u0283\u028ar \u02c8d\u0251\u02d0kt\u0259r \u02c8h\u0251\u02d0d\u0292\u026az w\u026al si\u02d0 ju\u02d0 \u00e6z su\u02d0n \u00e6z hi\u02d0 k\u00e6n./",
      keywords: ["as soon as he can"],
      explanationAi: "L\u1ec5 t\u00e2n xoa d\u1ecbu.",
      properNouns: ["Dr. Hodges"],
      tokenCount: 13,
