      startTime: 695.0,
      endTime: 716.8,
      text: "And here near apogee, we gimbal the engine to exert a torque that executes a pitchover maneuver to flip the rocket by 180 degrees.",
      translationVi: "V\u00e0 \u1edf \u0111\u00e2y, ngay g\u1ea7n \u0111i\u1ec3m vi\u1ec5n \u0111\u1ecba, ch\u00fang ta s\u1ebd xoay kh\u1edbp \u0111\u1ed9ng c\u01a1 \u0111\u1ec3 t\u1ea1o ra m\u1ed9t m\u00f4-men xo\u1eafn th\u1ef1c hi\u1ec7n c\u00fa \u0111i\u1ec1u \u0111\u1ed9ng ch\u00fai m\u0169i l\u1ed9n ng\u01b0\u1ee3c t\u00ean l\u1eeda \u0111\u00fang 180 \u0111\u1ed9.",
