      ipaUs: "/w\u025bl, a\u026a \u0261\u026av \u0111o\u028az tu\u02d0 \u02c8\u025bvriw\u028cn. \u00e6nd ju\u02d0 h\u00e6v tu\u02d0 \u02cc\u028cnd\u0259r\u02c8st\u00e6nd, \u02c8\u0283\u025bld\u0259n, \u00f0\u00e6t wa\u026al j\u028a\u0259r m\u00e6\u03b8 \u026az \u02cc\u03b8i\u02d0\u0259\u02c8r\u025bt\u026akli k\u0259\u02c8r\u025bkt, wi\u02d0 du\u02d0 n\u0251\u02d0t h\u00e6v \u00f0\u0259 \u02c8t\u025bkn\u026ak\u0259l \u02ccke\u026ap\u0259\u02c8b\u026al\u0259ti tu\u02d0 \u02c8\u025bks\u026a\u02cckju\u02d0t \u026at./",
      keywords: ["theoretically correct", "technical capability", "execute it"],
      explanationAi: "Hodges th\u1eeba nh\u1eadn t\u00ednh to\u00e1n ch\u00ednh x\u00e1c nh\u01b0ng c\u00f4ng ngh\u1ec7 ch\u01b0a theo k\u1ecbp.",
