      ipaUs: "/a\u026a \u02c8p\u025c\u02d0rs\u0259n\u0259li fa\u026and \u00f0\u00e6t \u02c8v\u025bri \u02ccri\u02d0\u0259\u02c8\u0283\u028ar\u026a\u014b./",
