      ipaUs: "/a\u026a du\u02d0 n\u0251\u02d0t. du\u02d0 ju\u02d0 no\u028a ha\u028a tu\u02d0 \u02ccd\u026af\u0259\u02c8r\u025bn\u0283i\u02cce\u026at \u02c8\u028cnd\u0259r \u00f0i \u02c8\u026ant\u026a\u0261r\u0259l sa\u026an? no\u028a. o\u028a, du\u02d0 ju\u02d0 no\u028a \u02c8\u025bni\u03b8\u026a\u014b? a\u026a no\u028a ju\u02d0 \u0251\u02d0r \u026an ma\u026a sp\u0251\u02d0t./",
      keywords: ["differentiate under integral sign", "in my spot"],
