      keywords: ["big plastic crap house", "look better"],
      explanationAi: "C\u00e1i b\u1ed1t v\u1ec7 sinh di \u0111\u1ed9ng \u0111\u01b0\u1ee3c George Sr. v\u00e1c v\u1ec1 nh\u00e0.",
      properNouns: [],
