      endTime: 1140.0,
      text: "You wanted a toilet? Voila! Where did you get it? From the high school. We got like ten of them for visiting teams. Give it a whirl. I would rather die.",
      translationVi: "B\u00e0 mu\u1ed1n c\u00f3 th\u00eam nh\u00e0 v\u1ec7 sinh ch\u1ee9 g\u00ec? Xong r\u1ed3i \u0111\u00f3! - \u00d4ng ki\u1ebfm n\u00f3 \u1edf \u0111\u00e2u ra v\u1eady? - T\u1eeb tr\u01b0\u1eddng c\u1ea5p ba. Tr\u01b0\u1eddng ch\u00fang t\u00f4i c\u00f3 c\u1ea3 ch\u1ee5c c\u00e1i cho c\u00e1c \u0111\u1ed9i kh\u00e1ch \u0111\u1ebfn thi \u0111\u1ea5u. D\u00f9ng th\u1eed m\u1ed9t ph\u00e1t xem sao! - T\u00f4i th\u00e0 ch\u1ebft c\u00f2n h\u01a1n!",
      ipaUs: "/ju\u02d0 \u02c8w\u0251\u02d0nt\u026ad \u0259 \u02c8t\u0254\u026al\u0259t? vwa\u02d0\u02c8la\u02d0! w\u025br d\u026ad ju\u02d0 \u0261\u025bt \u026at? fr\u028cm \u00f0\u0259 ha\u026a sku\u02d0l. wi\u02d0 \u0261\u0251\u02d0t la\u026ak t\u025bn \u028cv \u00f0\u025bm f\u0254\u02d0r \u02c8v\u026az\u026at\u026a\u014b ti\u02d0mz. \u0261\u026av \u026at \u0259 w\u025c\u02d0rl. a\u026a w\u028ad \u02c8r\u00e6\u00f0\u0259r da\u026a./",
      keywords: ["voila", "give it a whirl", "rather die"],
      explanationAi: "Th\u00e0nh ng\u1eef 'give it a whirl' (th\u1eed l\u00e0m \u0111i\u1ec1u g\u00ec xem sao).",
