      keywords: ["rock bottom", "flashlight to the handle", "I am out"],
      explanationAi: "Th\u00e0nh ng\u1eef 'rock bottom' (m\u1ee9c t\u1ed3i t\u1ec7 nh\u1ea5t c\u00f3 th\u1ec3 ch\u1ea1m t\u1edbi).",
