      startTime: 1762.0,
      endTime: 1774.0,
      text: "Okay, what do we have so far? I am taking a bus. Fun fact about buses... Come on! Does he really think these facts are fun?",
      translationVi: "\u0110\u01b0\u1ee3c r\u1ed3i, n\u00e3y gi\u1edd ch\u00fang ta d\u1ecbch \u0111\u01b0\u1ee3c nh\u1eefng g\u00ec r\u1ed3i? - 'Con \u0111ang \u0111i m\u1ed9t chuy\u1ebfn xe bu\u00fdt. S\u1ef1 th\u1eadt th\u00fa v\u1ecb v\u1ec1 xe bu\u00fdt l\u00e0...' - Th\u00f4i \u0111i cho t\u00f4i nh\u1edd! N\u00f3 th\u1ef1c s\u1ef1 ngh\u0129 m\u1ea5y s\u1ef1 th\u1eadt \u0111\u00f3 l\u00e0 th\u00fa v\u1ecb \u0111\u1ea5y \u00e0?",
