      keywords: ["taking a bus", "fun fact about buses", "so far"],
      explanationAi: "Sheldon ch\u00e8n ki\u1ebfn th\u1ee9c b\u00ean l\u1ec1 v\u1ec1 xe bu\u00fdt v\u00e0o c\u1ea3 b\u1ee9c th\u01b0 b\u1ecf tr\u1ed1n.",
      properNouns: [],
