      ipaUs: "/n\u0251\u02d0t na\u028a. a\u026a h\u00e6v \u0261\u0251\u02d0t \u026at! hi\u02d0 \u026az \u02c8h\u025bd\u026ad tu\u02d0 r\u028csk. hi\u02d0 \u026az \u02c8\u0261o\u028a\u026a\u014b tu\u02d0 \u00f0\u0259 \u02c8h\u0251\u02d0sp\u026atl\u0329 tu\u02d0 si\u02d0 d\u0292\u0251\u02d0n. a\u026a w\u026al k\u0254\u02d0l \u00f0\u0259 p\u0259\u02c8li\u02d0s. \u02c8h\u025c\u02d0ri!/",
